const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),assert=require('node:assert/strict');
const root=path.join(__dirname,process.argv.includes('--paths')?'skill-tree-paths-20261006':'skill-tree-20261006'),api=require(path.join(root,'skill-tree.js')),html=fs.readFileSync(path.join(root,'index.html'),'utf8'),results=[];
const check=(n,f)=>{f();results.push(n)};
for(const m of html.matchAll(/<script(?:\s[^>]*)?>([\s\S]*?)<\/script>/g))new vm.Script(m[1]);for(const f of fs.readdirSync(root).filter(f=>f.endsWith('.js')))new vm.Script(fs.readFileSync(path.join(root,f),'utf8'),{filename:f});
const ctx={lv:2,adv:false,stage:0,cleared:[],stars:[],recipes:[],names:{guard:'防禦術',heal:'回復術'}};
const heal={k:'heal',cost:1,lv:2,pre:['guard']};
check('fresh characters own only defense and no counter/heal',()=>{const r=api.migrate(1,[],false);assert.deepEqual(r.learned,['guard']);assert.equal(r.points,0)});
check('every new level grants 1 point, skips grant multiple points exactly once',()=>{let r=api.migrate(1,[],false);r=api.grant(r,4);assert.equal(r.points,3);assert.deepEqual(api.grant(r,4),r);assert.deepEqual(api.grant(r,2),r);r=api.grant(r,5);assert.equal(r.points,4)});
check('click learning spends 1 point and duplicate learning does not spend again',()=>{const r=api.grant(api.migrate(1,[],false),2),a=api.purchase(r,heal,ctx);assert.equal(a.ok,true);assert.equal(a.record.points,0);assert.ok(a.record.learned.includes('heal'));const b=api.purchase(a.record,heal,ctx);assert.equal(b.ok,false);assert.equal(b.record.points,0);assert.equal(r.points,1)});
check('level, previous skill, points and advanced-class gates work independently',()=>{let r=api.migrate(1,[],false);assert.match(api.reason(r,heal,{...ctx,lv:1}),/Lv2/);assert.match(api.reason(r,heal,ctx),/還差/);r=api.grant(r,5);assert.match(api.reason(r,{...heal,pre:['revive']},ctx),/revive/);assert.match(api.reason(r,{...heal,adv:true},ctx),/轉職/)});
check('stage, node, boss discovery, star and recipe gates cannot be bypassed',()=>{const r=api.grant(api.migrate(1,[],false),10);for(const n of [{...heal,stage:2},{...heal,node:'7-王'},{...heal,spark:'ignis',sparkName:'炎王'},{...heal,star:'ram'},{...heal,recipe:true}])assert.ok(api.reason(r,n,ctx));r.found.push('heal');assert.equal(api.reason(r,{...heal,spark:'ignis'},ctx),'')});
check('old learned abilities and counter preserved free with spare level points',()=>{const r=api.migrate(10,['heal','revive','ultima','sweep','guard'],true);assert.equal(r.points,9);assert.equal(r.legacy,true);assert.ok(['heal','revive','ultima','sweep','counter'].every(k=>r.learned.includes(k)));assert.equal(r.learned.filter(k=>k==='guard').length,1)});
check('reload preserves purchased ownership and spent points',()=>{let r=api.purchase(api.grant(api.migrate(1,[],false),2),heal,ctx).record;const s=api.normalize(JSON.parse(JSON.stringify({classes:{support:r}})));assert.equal(s.classes.support.points,0);assert.ok(s.classes.support.learned.includes('heal'));assert.equal(api.grant(s.classes.support,2).points,0)});
check('corrupt records normalized without deleting old save keys',()=>{const s=api.normalize({classes:{support:{points:-5,high:'abc',learned:['guard','guard',9]},bad:{}}});assert.deepEqual(s.classes.support.learned,['guard']);assert.equal(s.classes.support.high,1);assert.equal(s.classes.support.points,0);assert.equal(s.classes.bad,undefined);assert.ok(!/removeItem|localStorage\.clear/.test(fs.readFileSync(path.join(root,'skill-tree.js'),'utf8')))});
check('both original spark auto-learning paths disabled by tree module',()=>{assert.equal((html.match(/!window\.SkillTree && u\.team === 'hero' && u\.cls && sk\.kind === 'phys'/g)||[]).length,2)});
check('native map and cinematic counters use the same learned ability gate',()=>{assert.match(html,/SkillTree\.runtime\.canCounter\(d\)/);assert.match(html,/counter && canCounter\(prim, u\)/);assert.match(html,/prim\.alive && u\.alive && canCounter\(prim, u\)/)});
check('fresh supplies only herbs; existing saved inventory remains preferred',()=>{assert.match(html,/START_BAG = \(\) => \(\{ herb: 3 \}\)/);assert.match(html,/LS\('babylon-bag-v1', null\) \|\| START_BAG\(\)/)});
check('actual counter gate still rejects dead, out-of-range, rare enemies',()=>{
 const start=html.indexOf('  function canCounter(d, a)'),end=html.indexOf('\n  /* ── 角色圖',start);const c={window:{SkillTree:true},SkillTree:{runtime:{canCounter:u=>!u.cls||u.learned}},MONS:{rare:{rare:1}},SK:{strike:{kind:'phys',rng:[1,1]}},man:(a,b)=>Math.abs(a.x-b.x)};vm.createContext(c);vm.runInContext(html.slice(start,end),c);const hero={alive:true,hp:10,cls:'support',basic:'strike',x:0},foe={alive:true,hp:10,basic:'strike',x:1};assert.equal(c.canCounter(hero,foe),false);assert.equal(c.canCounter({...hero,learned:true},foe),true);assert.equal(c.canCounter(foe,hero),true);assert.equal(c.canCounter({...hero,learned:true,hp:0},foe),false);assert.equal(c.canCounter({...foe,x:4},hero),false);assert.equal(c.canCounter({...foe,kind:'rare'},hero),false);
});
check('fresh opening basics and class trees retain valid prerequisites',()=>{
 // Use declarations from the actual game rather than duplicate class data.
 const c={window:{},document:{documentElement:{dataset:{}},createElement:()=>({}),querySelector:()=>null,querySelectorAll:()=>[]},G:{party:[],phase:'title'},TEST:{on:false},ROSTER:{},CLEARED:new Set(),STARS_GOT:new Set(),ALCHEMY:new Set(),PROGRESS:0,STAR_DEF:[],localStorage:{setItem(){}},LS:()=>null,rosterOf:()=>({lv:1,adv:false}),learnedSkills:()=>[],starSkills:()=>[],renderSetup(){},openStatus(){},openWorld(){},perform(){},learnSkill(){},partyList:()=>[],console};vm.createContext(c);
 vm.runInContext(html.slice(html.indexOf('const CLASSES ='),html.indexOf('/* ── 招式 ── */')),c);
 vm.runInContext(html.slice(html.indexOf('const SK ='),html.indexOf('/* ── 道具',html.indexOf('const SK ='))),c);
 vm.runInContext(html.slice(html.indexOf('const LEARN ='),html.indexOf('\n};',html.indexOf('const LEARN ='))+3),c);
 vm.runInContext(html.slice(html.indexOf('Object.assign(SK, {'),html.indexOf('/* 煉金術士學過的')),c);
 vm.runInContext('var MONS={ignis:{nm:"炎王"},selena:{nm:"冰后"},odin:{nm:"奧丁"},hanzo:{nm:"半藏"}};',c);
 if(process.argv.includes('--paths'))c.SkillPaths=require(path.join(root,'skill-paths.js'));
 vm.runInContext(fs.readFileSync(path.join(root,'skill-tree.js'),'utf8'),c);const rt=c.window.SkillTree.runtime;
 for(const cls of ['warrior','mage','support','rogue','summoner','sorcerer','alchemist']){const l=rt.loadout(cls);assert.deepEqual(Array.from(l.skills),['guard']);assert.equal(l.counter,false);const catalog=rt.catalog(cls),keys=catalog.map(n=>n.k);for(const n of catalog)for(const pre of n.pre)assert.ok(keys.includes(pre),cls+' '+n.k+' '+pre);const final=catalog.filter(n=>n.ultimate);assert.equal(final.length,1);assert.equal(final[0].lv,10);assert.equal(final[0].cost,3);assert.equal(final[0].adv,true);assert.equal(final[0].k,api.PATHS[cls].ultimate);}
 assert.equal(rt.loadout('warrior').basic,'strike');assert.equal(rt.loadout('support').basic,'strike');assert.equal(rt.canCounter({team:'enemy'}),true);assert.equal(rt.canCounter({team:'hero',cls:'support'}),false);
 const old=JSON.stringify(rt.state);c.TEST.on=true;rt.level({cls:'support',lv:10});assert.equal(JSON.stringify(rt.state),old);assert.equal(rt.buy('support','heal').ok,false);
 const wheel=rt.wheel('warrior');assert.ok(!/NaN|undefined|Infinity/.test(wheel));assert.match(wheel,/ Q /);
 if(process.argv.includes('--paths')){assert.equal((wheel.match(/class="sg-slot /g)||[]).length,28);assert.equal((wheel.match(/class="sg-pipe"/g)||[]).length,21);assert.ok(!/tree-groove/.test(wheel));for(const cls of ['warrior','mage','support','rogue','summoner','sorcerer','alchemist'])for(const n of rt.catalog(cls)){const m=c.SkillPaths.routeModel(rt.catalog(cls),n.k);assert.ok(m.nodes.some(v=>v.k===n.k));assert.ok(m.nodes.every(v=>(v.pre||[]).every(k=>m.points[k])));for(let i=1;i<m.nodes.length;i++){const a=m.points[m.nodes[i-1].k],b=m.points[m.nodes[i].k];assert.ok(Math.hypot(a[0]-b[0],a[1]-b[1])>=148);}}}
 else{const total=['warrior','mage','support','rogue','summoner','sorcerer','alchemist'].reduce((n,cls)=>n+rt.catalog(cls).length-1,0);assert.equal((wheel.match(/class="tree-groove /g)||[]).length,total);assert.match(wheel,/treePocket/);assert.match(wheel,/treeElixir/);assert.equal((wheel.match(/class="tree-wheel-end"/g)||[]).length,7);}
});
if(process.argv.includes('--paths'))check('continuous liquid front reaches the next node before pocket fills',()=>{const p=require(path.join(root,'skill-paths.js'));assert.deepEqual(p.flowAt(0),{travel:0,fill:0,phase:'travel',done:false});const a=p.flowAt(1050);assert.equal(a.travel,.5);assert.equal(a.fill,0);assert.equal(a.phase,'travel');assert.equal(p.flowAt(2099).fill,0);assert.equal(p.flowAt(2100).travel,1);assert.equal(p.flowAt(2100).fill,0);assert.equal(p.flowAt(2550).fill,.5);assert.equal(p.flowAt(3300).done,true);const source=fs.readFileSync(path.join(root,'skill-tree.js'),'utf8');assert.match(source,/getPointAtLength\(t\.length\*f\.travel\)/);assert.match(source,/stopFlow\(\)/);assert.match(source,/cancelAnimationFrame/);assert.match(source,/t\.path\.style\.strokeDashoffset=String\(1-f\.travel\)/);});
