const qa=`<script>artReady.then(()=>{const nav=document.createElement('nav');nav.id='treeQA';nav.style='position:fixed;top:0;left:0;right:0;z-index:240;background:#142631;color:white;padding:5px;font:11px sans-serif';nav.innerHTML='<button id="tqParty">測試開局</button><button id="tqLevel">升級一級</button><button id="tqReport">核對技能</button><button id="tqBattle">戰鬥選單</button><button id="tqExitBattle">離開測試戰鬥</button><button id="tqHide">收起測試</button><output id="tqOutput"></output>';document.body.appendChild(nav);const report=()=>{const sample={team:'hero',cls:'support',basic:'strike',alive:true,hp:10,x:0,z:0};const foe={team:'enemy',basic:'strike',alive:true,hp:10,x:1,z:0};document.querySelector('#tqOutput').textContent=JSON.stringify({edition:document.documentElement.dataset.skillEdition,phase:G.phase,party:G.party.filter(u=>u.cls).map(u=>({cls:u.cls,lv:u.lv,basic:u.basic,skills:u.skills})),tree:SkillTree.runtime.state,heroCounter:duelQA.canCounter(sample,foe),enemyCounter:duelQA.canCounter(foe,sample),bag:G.bag});};document.querySelector('#tqParty').onclick=()=>{setup.picks=[{cls:'warrior',name:'亞瑟',el:'地',col:5,lead:true},{cls:'support',name:'艾莉',el:'光',sex:'f'}];curNode=NODES.find(n=>n.id==='1-1');buildBattle();chooseZone(ZONES[0]);$('#deploy').hidden=true;$('#bottom').hidden=true;G.phase='title';show('#sTitle');report();};document.querySelector('#tqLevel').onclick=()=>{for(const u of G.party.filter(u=>u.cls))gainExp(u,expNext(u.lv)-(u.exp||0));recordParty();report();};document.querySelector('#tqReport').onclick=report;document.querySelector('#tqBattle').onclick=()=>{cur=G.party.find(u=>u.cls==='support');G.phase='battle';show('#gl');mode='act';refreshTurn();openSkills();report();};document.querySelector('#tqExitBattle').onclick=()=>{G.phase='title';$('#menu').hidden=true;$('#bottom').hidden=true;show('#sTitle');report();};document.querySelector('#tqHide').onclick=()=>nav.style.display='none';});</script>`;
const freezeQA=`<script>artReady.then(()=>{const nav=document.querySelector('#treeQA');nav.style='position:fixed;bottom:0;left:0;right:0;z-index:240;background:#142631;color:white;padding:5px;font:10px sans-serif';nav.querySelector('output').style.display='none';const steps=[0,175,350,525,700,875,1050,1225,1400,1575,1750,1925,2100,2325,2550,2775,3000,3300];nav.insertAdjacentHTML('afterbegin','<button id="pqFreeze">逐格流動示範</button><select id="pqTime" aria-label="動畫時間">'+steps.map(t=>'<option value="'+t+'">'+(t<=2100?'管內 '+Math.round(t/21)+'%':'填槽 '+Math.min(100,Math.round((t-2100)/9))+'%')+'</option>').join('')+'</select>');document.querySelector('#pqFreeze').onclick=()=>{SkillTree.runtime.animateRoute('warrior','counter',true);SkillTree.runtime.flowAt(Number(document.querySelector('#pqTime').value));};document.querySelector('#pqTime').onchange=e=>SkillTree.runtime.flowAt(Number(e.target.value));});</script>`;
if(process.argv.includes('--serve'))for(const port of(process.argv.includes('--paths')?[4188,4189]:[4186,4187]))require('node:http').createServer((req,res)=>{const url=new URL(req.url,'http://localhost'),file=path.resolve(root,'.'+decodeURIComponent(url.pathname==='/'?'/index.html':url.pathname));if(!file.startsWith(root+path.sep)||!fs.existsSync(file)){res.writeHead(404).end();return;}const mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.jpg':'image/jpeg','.png':'image/png','.webp':'image/webp'};res.writeHead(200,{'Content-Type':mime[path.extname(file)]||'application/octet-stream','Cache-Control':'no-store'});if(file.endsWith('index.html')){let page=fs.readFileSync(file,'utf8');if(port===4187||port===4189)page=page.replace('<script src="skill-tree.js', '<script>ROSTER={support:{lv:10,exp:0,adv:true},warrior:{lv:10,exp:0,adv:true,learned:["flamesword"]}};PROGRESS=5;</script><script src="skill-tree.js');res.end(page.replace('</body>',qa+(process.argv.includes('--paths')?freezeQA:'')+'</body>'));}else fs.createReadStream(file).pipe(res)}).listen(port,'127.0.0.1',()=>console.log('Skill-tree QA ready:'+port));
